-- Seed gerado por assets/gerador-avaliacao-discursiva (não editar à mão; fora do Git).
-- Rodar depois de database/2026-10-01-respostas-discursivas.sql. Idempotente.
-- A avaliação nasce BLOQUEADA (ativo = false): o professor libera no índice de atividades.
do $$
declare
  v_aula bigint;
  v_atividade bigint;
begin
  select a.id into v_aula from public.aulas a join public.materia m on m.id = a.materia_id
    where m.descricao = 'Fundamentos de UI / UX' and a.numero = 16
    order by a.id limit 1;
  if v_aula is null then
    raise exception 'Aula 16 da matéria não encontrada';
  end if;

  insert into public.atividade (nome_atividade, status, aula_id, descricao, pagina,
      total_itens, ativo)
    values ('Atividade Prática — Aula 16', 'PENDENTE', v_aula, 'Atividade — Atividade Prática — Aula 16 (20 questões discursivas)',
      '/MATERIAIS/TECNICO-INFORMATICA-INTERNET/FUNDAMENTOS-DE-UI-UX/ATIVIDADES/ATIVIDADE-PRATICA-AULA-16.html', 20, false)
    on conflict (pagina) do update set aula_id = excluded.aula_id,
      descricao = excluded.descricao, total_itens = excluded.total_itens
    returning id into v_atividade;

  delete from public.topico_discursivo where atividade_id = v_atividade;
  insert into public.topico_discursivo (atividade_id, item, topico, enunciado, pontos,
      resposta_esperada, criterios) values
      (v_atividade, 1, 1, 'Classifique o primeiro comentário e justifique', 0.2, 'Classificar "Achei a cor de fundo sem graça" como opinião, por ser uma impressão estética individual e um gosto pessoal que não impede a tarefa de agendar.', 'Nota cheia: classifica como opinião e justifica como gosto pessoal ou impressão estética, sem impedir a tarefa. Metade: classifica como opinião, mas sem justificar, ou justifica de forma vaga. Zero: classifica como desejo ou necessidade, em branco ou fora do tema.'),
      (v_atividade, 1, 2, 'Classifique o segundo comentário e justifique', 0.4, 'Classificar "Seria bom ter sons ao confirmar" como desejo, por ser um recurso extra que torna o uso agradável, mas não é necessário para concluir o agendamento.', 'Nota cheia: classifica como desejo e justifica que é recurso extra que não impede a tarefa central. Metade: classifica como desejo, sem explicar por que não impede a tarefa, ou o contrário. Zero: classifica como necessidade ou opinião, em branco ou fora do tema.'),
      (v_atividade, 1, 3, 'Classifique o terceiro comentário e justifique', 0.4, 'Classificar "Não consigo saber se o horário foi salvo" como necessidade, porque sem a confirmação a pessoa não conclui a jornada com eficácia e pode repetir ou errar o agendamento.', 'Nota cheia: classifica como necessidade e justifica pela falta de confirmação que impede concluir a tarefa com eficácia. Metade: classifica como necessidade, mas justifica de forma incompleta. Zero: classifica como opinião ou desejo, em branco ou fora do tema.'),
      (v_atividade, 2, 1, 'Defina desejo com suas palavras', 0.2, 'Desejo é um recurso extra que torna o uso mais agradável, mas não impede a realização da tarefa central.', 'Nota cheia: define desejo como recurso extra ou agradável que não impede a tarefa, com as próprias palavras. Metade: define desejo de modo parcial, sem deixar claro que a tarefa continua possível. Zero: define como condição essencial, em branco ou fora do tema.'),
      (v_atividade, 2, 2, 'Defina necessidade com suas palavras', 0.4, 'Necessidade é a condição essencial para a pessoa concluir sua jornada com eficácia, acessibilidade e sem erros.', 'Nota cheia: define necessidade como condição essencial para concluir a tarefa com eficácia, acessibilidade ou sem erros. Metade: define necessidade mencionando só um dos aspectos (por exemplo, só "é importante"). Zero: define como recurso extra ou estético, em branco ou fora do tema.'),
      (v_atividade, 2, 3, 'Indique a prioridade e explique o motivo', 0.4, 'A prioridade deve ser maior no caso do campo obrigatório que não aparece, porque é uma necessidade que impede o cadastro de ser concluído, enquanto a personalização de cores é um desejo.', 'Nota cheia: indica o cadastro (necessidade) como prioridade maior e explica que impede a conclusão da tarefa, enquanto a cor é desejo. Metade: indica a prioridade correta, mas sem explicar o motivo. Zero: indica o desejo de cores como prioridade, em branco ou fora do tema.'),
      (v_atividade, 3, 1, 'Identifique a sugestão literal e a dor real', 0.2, 'A sugestão literal é "fonte vermelha gigante", e a dor real pode ser a falta de contraste ou de um aviso claro sobre o erro do formulário.', 'Nota cheia: identifica a sugestão literal (fonte vermelha gigante) e a dor real (falta de contraste ou aviso claro de erro). Metade: identifica a sugestão, mas a dor real de forma vaga ou incompleta. Zero: não identifica a sugestão ou a dor, em branco ou fora do tema.'),
      (v_atividade, 3, 2, 'Explique por que não se deve aceitar a sugestão literal sem análise', 0.4, 'A sugestão literal pode não resolver o problema e até criar novo atrito, como poluição visual; por isso a regra de ouro manda descobrir o problema subjacente antes de aceitar qualquer sugestão.', 'Nota cheia: explica que a sugestão literal pode não resolver a dor real ou piorar a tela, e cita a regra de ouro (descobrir o problema antes de aceitar). Metade: cita a regra de ouro sem explicar o risco da sugestão literal. Zero: aceita a sugestão sem análise, em branco ou fora do tema.'),
      (v_atividade, 3, 3, 'Descreva o que você investigaria antes de decidir', 0.4, 'Antes de decidir, investigaria como as pessoas usam a tela, observando ou entrevistando usuários, verificando se percebem a mensagem de erro e testando contraste e posição do aviso.', 'Nota cheia: descreve pelo menos duas ações de investigação (observar o uso, entrevistar, verificar a percepção do erro, testar contraste ou posição do aviso). Metade: descreve apenas uma ação ou ações genéricas, como "perguntar aos usuários". Zero: não descreve investigação, em branco ou fora do tema.'),
      (v_atividade, 4, 1, 'Indique o primeiro passo da triagem', 0.2, 'O primeiro passo é diferenciar opiniões individuais de necessidades funcionais, separando o que é gosto pessoal do que é exigência para uso da tela.', 'Nota cheia: indica diferenciar opiniões de necessidades funcionais como primeiro passo. Metade: indica a ideia de separar os feedbacks, sem citar a diferença entre opinião e necessidade. Zero: indica outro passo como primeiro, em branco ou fora do tema.'),
      (v_atividade, 4, 2, 'Indique o segundo passo, relacionado a agrupar e identificar padrões', 0.4, 'O segundo passo é agrupar as respostas em categorias temáticas e identificar padrões, para que as repetições e as tendências apareçam.', 'Nota cheia: indica agrupar em categorias temáticas e identificar padrões. Metade: indica apenas agrupar, sem falar em padrões, ou o contrário. Zero: indica outro passo, em branco ou fora do tema.'),
      (v_atividade, 4, 3, 'Indique o terceiro passo, relacionado a aplicar a matriz de priorização', 0.4, 'O terceiro passo é aplicar a matriz técnica de priorização para tomar a decisão, depois de mapear os conflitos entre pedidos.', 'Nota cheia: indica aplicar a matriz técnica de priorização para decidir. Metade: indica priorizar sem citar a matriz técnica. Zero: indica outro passo, em branco ou fora do tema.'),
      (v_atividade, 5, 1, 'Indique o que cada grupo pede', 0.2, 'Os estudantes pedem agilidade em smartphones e atalhos para notas; os professores exigem campos completos para lançamento de chamadas e relatórios exportáveis.', 'Nota cheia: indica corretamente o pedido dos dois grupos (agilidade, atalhos e smartphone; campos completos e relatórios). Metade: indica o pedido de só um dos grupos, ou de forma incompleta. Zero: inverte os pedidos ou não responde, em branco ou fora do tema.'),
      (v_atividade, 5, 2, 'Indique em qual tela ou etapa os pedidos se chocam', 0.4, 'O choque ocorre na tela de lançamento de chamadas e de notas, onde o formulário precisa ter todos os campos e, ao mesmo tempo, ser rápido de preencher no celular.', 'Nota cheia: indica a tela ou etapa (lançamento de chamadas ou de notas, formulário) onde os pedidos se chocam. Metade: indica uma tela ou etapa de forma genérica, como "o aplicativo". Zero: não indica tela ou etapa, em branco ou fora do tema.'),
      (v_atividade, 5, 3, 'Explique por que o choque ocorre, com base nas necessidades de cada perfil', 0.4, 'Os estudantes querem rapidez e pouco preenchimento porque usam o celular no dia a dia; os professores precisam dos dados completos para lançar as chamadas e gerar relatórios. O choque nasce de necessidades diferentes na mesma tela.', 'Nota cheia: explica o choque com base nas necessidades de cada perfil (rapidez e pouca digitação dos estudantes; dados completos e relatórios dos professores). Metade: explica o choque sem relacionar com as necessidades de cada perfil. Zero: não explica, em branco ou fora do tema.'),
      (v_atividade, 6, 1, 'Classifique a proposta 1 e justifique', 0.2, 'A proposta 1 (reescrever o fluxo de login, alto esforço e grande benefício estrutural) fica no quadrante Estratégico, pois tem alto valor estrutural e exige planejamento técnico aprofundado.', 'Nota cheia: classifica como Estratégico e justifica pelo alto valor estrutural com alto esforço. Metade: classifica corretamente, sem justificar, ou justifica só pelo esforço. Zero: classifica como Vitória Rápida, Descartar ou Secundário, em branco ou fora do tema.'),
      (v_atividade, 6, 2, 'Classifique a proposta 2 e justifique', 0.4, 'A proposta 2 (ajustar o espaçamento de um botão, baixo esforço e impacto imediato) fica no quadrante Vitória Rápida, pois melhora a usabilidade diária com pouco trabalho.', 'Nota cheia: classifica como Vitória Rápida e justifica pelo baixo esforço e impacto imediato. Metade: classifica corretamente, sem justificar, ou justifica só por um dos fatores. Zero: classifica como Estratégico, Descartar ou Secundário, em branco ou fora do tema.'),
      (v_atividade, 6, 3, 'Classifique a proposta 3 e justifique', 0.4, 'A proposta 3 (tema decorativo, alto esforço e pouco benefício) fica no quadrante Descartar, pois tem alto esforço e baixo benefício para quem navega.', 'Nota cheia: classifica como Descartar e justifica pelo alto esforço com baixo benefício. Metade: classifica corretamente, sem justificar, ou justifica só por um dos fatores. Zero: classifica como Estratégico ou Vitória Rápida, em branco ou fora do tema.'),
      (v_atividade, 7, 1, 'Explique o critério de impacto e o critério de relevância', 0.2, 'Impacto mede quanto a demanda melhora a resolução de tarefas ou a autonomia do usuário; relevância mede a proporção de usuários afetados pelo recurso.', 'Nota cheia: explica impacto (melhora na tarefa ou autonomia) e relevância (proporção de usuários afetados). Metade: explica só um dos dois critérios, ou explica os dois de forma vaga. Zero: troca os conceitos, em branco ou fora do tema.'),
      (v_atividade, 7, 2, 'Explique o critério de esforço', 0.4, 'Esforço mede a complexidade técnica e o tempo de desenvolvimento necessários para entregar a demanda.', 'Nota cheia: explica esforço como complexidade técnica e tempo de desenvolvimento. Metade: explica esforço só como "trabalho" ou "dificuldade", sem citar técnica ou tempo. Zero: não explica ou confunde com impacto, em branco ou fora do tema.'),
      (v_atividade, 7, 3, 'Explique como a prioridade resulta da combinação dos demais critérios', 0.4, 'A prioridade é a posição final da demanda na fila de produção e resulta da combinação entre impacto e relevância (benefício) e esforço (custo): muito benefício e pouco esforço sobem na fila.', 'Nota cheia: explica a prioridade como posição final na fila e como combinação de impacto, relevância e esforço. Metade: diz que a prioridade depende dos outros critérios, sem explicar como se combinam. Zero: não relaciona prioridade com os critérios, em branco ou fora do tema.'),
      (v_atividade, 8, 1, 'Indique o pedido com maior adesão e sua proporção', 0.2, 'O pedido com maior adesão é a clareza de avisos sobre tarefas, com 52 pedidos em 100 formulários, ou seja, 52% dos respondentes.', 'Nota cheia: indica clareza de avisos e a proporção de 52% (ou 52 de 100). Metade: indica o pedido correto, sem a proporção, ou a proporção sem o nome do pedido. Zero: indica outro pedido, em branco ou fora do tema.'),
      (v_atividade, 8, 2, 'Explique por que pedidos com pouca adesão não devem liderar a fila sozinhos', 0.4, 'Pedidos com pouca adesão, como sons (6%), refletem a preferência de poucas pessoas; liderar a fila com eles desviaria o projeto do que a maioria precisa e gera ruído desnecessário.', 'Nota cheia: explica que pouca adesão reflete preferência de poucos, que não deve liderar a fila, e relaciona com a relevância (proporção de usuários). Metade: diz que não devem liderar, sem explicar o motivo. Zero: afirma que pouca adesão deve liderar, em branco ou fora do tema.'),
      (v_atividade, 8, 3, 'Diga qual decisão de priorização você recomendaria e por quê', 0.4, 'Recomendaria priorizar a clareza dos avisos sobre tarefas, por ser o pedido de maior adesão e por ter ligação direta com a conclusão das tarefas; a legibilidade vem em seguida, e os sons ficam por último.', 'Nota cheia: recomenda priorizar a clareza de avisos e justifica pela adesão e pela relação com as tarefas. Metade: recomenda o pedido correto, sem justificar com a adesão ou com as tarefas. Zero: recomenda sons ou outro pedido de baixa adesão como prioridade, em branco ou fora do tema.'),
      (v_atividade, 9, 1, 'Indique a primeira etapa e o que ela envolve', 0.2, 'A primeira etapa é mapear o atrito, identificando onde os pedidos se chocam na mesma tela.', 'Nota cheia: indica mapear o atrito e explica que é identificar onde os pedidos se chocam na mesma tela. Metade: indica a etapa, sem explicar o que ela envolve. Zero: indica outra etapa como primeira, em branco ou fora do tema.'),
      (v_atividade, 9, 2, 'Explique a etapa de ouvir os lados', 0.4, 'Ouvir os lados é compreender a rotina e as limitações de cada perfil, sem favorecer nenhum deles, antes de propor uma solução.', 'Nota cheia: explica ouvir os lados como compreender a rotina e as limitações de cada perfil, de forma neutra. Metade: explica apenas "ouvir" ou "conversar", sem a rotina e as limitações. Zero: confunde com outra etapa ou não responde, em branco ou fora do tema.'),
      (v_atividade, 9, 3, 'Explique a etapa de testar uma opção que atenda o núcleo dos dois lados', 0.4, 'Testar opção é desenhar uma alternativa que atenda o núcleo das necessidades dos dois lados, sem que nenhum lado perca o essencial.', 'Nota cheia: explica que é desenhar uma alternativa que atenda o núcleo de ambos os lados. Metade: explica a etapa de forma genérica, sem o núcleo dos dois lados. Zero: confunde com validação ou não responde, em branco ou fora do tema.'),
      (v_atividade, 10, 1, 'Indique a etapa da mediação que trata dessa validação', 0.2, 'A validação é tratada pela quarta etapa da mediação, validar dados.', 'Nota cheia: indica a quarta etapa, validar dados. Metade: cita a validação sem indicar a etapa. Zero: indica outra etapa, em branco ou fora do tema.'),
      (v_atividade, 10, 2, 'Descreva como confirmar a eficácia da alternativa com os usuários', 0.4, 'Confirmaria a eficácia da alternativa com um teste rápido com os usuários dos dois grupos, observando se a alternativa resolve o problema de cada um.', 'Nota cheia: descreve um teste rápido com usuários dos dois grupos, verificando se a alternativa resolve o problema. Metade: descreve o teste sem envolver os dois grupos, ou sem o objetivo de confirmar a eficácia. Zero: não descreve teste, em branco ou fora do tema.'),
      (v_atividade, 10, 3, 'Explique o que fazer se o teste mostrar que a alternativa não resolve o conflito', 0.4, 'Se o teste mostrar que a alternativa não resolve o conflito, volta-se às etapas anteriores, ouvindo de novo os lados e desenhando outra opção antes de fechar a decisão.', 'Nota cheia: indica voltar às etapas anteriores (ouvir os lados ou testar nova opção) antes de decidir. Metade: diz que é preciso mudar a alternativa, sem indicar como. Zero: diz que deve manter a alternativa mesmo assim, em branco ou fora do tema.'),
      (v_atividade, 11, 1, 'Defina amabilidade com suas palavras', 0.2, 'Amabilidade é ouvir com respeito e explicar tecnicamente os limites do projeto, sem hostilidade, mantendo a cooperação da equipe.', 'Nota cheia: define amabilidade como ouvir com respeito e explicar limites técnicos sem hostilidade. Metade: define só como "ser educado" ou "não brigar", sem o aspecto técnico. Zero: define como aceitar todas as propostas, em branco ou fora do tema.'),
      (v_atividade, 11, 2, 'Explique em que a discordância deve se basear', 0.4, 'A discordância deve se basear no impacto técnico da proposta na usabilidade (por exemplo, a poluição visual), nunca na inteligência ou no valor da pessoa que sugeriu.', 'Nota cheia: indica que a crítica recai sobre o impacto técnico da proposta na usabilidade e não sobre a pessoa. Metade: indica a crítica à proposta, sem dizer que não deve recair sobre a pessoa. Zero: indica crítica à pessoa, em branco ou fora do tema.'),
      (v_atividade, 11, 3, 'Descreva como você conduziria a conversa com o colega', 0.4, 'Conduziria a conversa ouvindo o colega, reconhecendo a intenção dele, apontando com argumentos o impacto da função na tela principal e sugerindo uma alternativa que mantenha o objetivo.', 'Nota cheia: descreve ouvir o colega, reconhecer a intenção, apontar o impacto técnico com argumentos e sugerir alternativa. Metade: descreve apenas parte dessas ações (por exemplo, só apontar o impacto). Zero: descreve discussão hostil ou não responde, em branco ou fora do tema.'),
      (v_atividade, 12, 1, 'Explique por que a resposta seca deve ser evitada', 0.2, 'A resposta seca, como "não faremos porque não cabe", gera atrito e desrespeita o usuário, pois não explica o motivo técnico da recusa.', 'Nota cheia: explica que a resposta seca desrespeita o usuário ou gera atrito, por não explicar o motivo. Metade: diz que a resposta seca não é boa, sem explicar o motivo. Zero: defende a resposta seca, em branco ou fora do tema.'),
      (v_atividade, 12, 2, 'Indique o motivo técnico da recusa', 0.4, 'O motivo técnico é que a função desviaria o foco da tarefa principal e aumentaria a poluição visual da tela.', 'Nota cheia: indica o motivo técnico (desvio do foco da tarefa principal e/ou aumento da poluição visual, ou outro impacto na navegação). Metade: indica um motivo genérico, como "não é necessário". Zero: não indica motivo, em branco ou fora do tema.'),
      (v_atividade, 12, 3, 'Ofereça uma alternativa viável ao usuário', 0.4, 'Ofereceria uma alternativa viável que atenda o objetivo do usuário sem prejudicar a tela, por exemplo, um aviso discreto ou um recurso na área de avisos.', 'Nota cheia: oferece uma alternativa viável que atende ao objetivo do usuário e não prejudica a interface. Metade: oferece alternativa vaga, sem ligação com o objetivo do usuário. Zero: não oferece alternativa, em branco ou fora do tema.'),
      (v_atividade, 13, 1, 'Explique por que decisões não devem ficar só na memória ou em conversas informais', 0.2, 'Decisões não podem ficar só na memória ou em conversas informais, pois sem registro com evidência técnica viram disputa de egos e não podem ser conferidas pela equipe.', 'Nota cheia: explica que decisões precisam ser registradas para que a equipe as leia e confira, com evidência técnica. Metade: diz que é preciso registrar, sem explicar o motivo. Zero: diz que conversas informais bastam, em branco ou fora do tema.'),
      (v_atividade, 13, 2, 'Indique os campos essenciais do registro de decisão', 0.4, 'Os campos essenciais são a proposta, o motivo técnico da decisão (por que foi aceita ou recusada), a evidência observada e a alternativa proposta.', 'Nota cheia: indica pelo menos três campos (proposta, motivo técnico, evidência observada, alternativa). Metade: indica um ou dois campos apenas. Zero: não indica campos, em branco ou fora do tema.'),
      (v_atividade, 13, 3, 'Explique como o registro protege a equipe contra reaberturas indevidas', 0.4, 'O registro protege porque, se alguém quiser reabrir um pedido já decidido, basta mostrar o documento com o motivo técnico e a evidência, evitando discussões de opinião.', 'Nota cheia: explica que o registro mostra o motivo técnico e a evidência, evitando discussões baseadas em opinião. Metade: diz que o registro ajuda, sem explicar como protege. Zero: não explica, em branco ou fora do tema.'),
      (v_atividade, 14, 1, 'Explique o objetivo da validação de dados', 0.2, 'O objetivo da validação de dados é confirmar com os usuários que a alternativa proposta resolve o problema real, evitando que uma decisão baseada em achismo entre em produção.', 'Nota cheia: explica que o objetivo é confirmar com usuários que a alternativa resolve o problema real, evitando achismo. Metade: explica que é confirmar com usuários, sem o objetivo de resolver o problema real. Zero: não explica ou confunde com teste técnico, em branco ou fora do tema.'),
      (v_atividade, 14, 2, 'Descreva um método de validação adequado ao contexto da escola', 0.4, 'Um método adequado é observar os alunos usando a alternativa em um horário real de aula, sem interferir, e registrar o tempo e os erros.', 'Nota cheia: descreve um método de observação em contexto real (horário de aula) registrando tempo e erros. Metade: descreve um método genérico, como "perguntar aos alunos", sem contexto real. Zero: não descreve método, em branco ou fora do tema.'),
      (v_atividade, 14, 3, 'Explique como a validação previne a reabertura desnecessária de pedidos', 0.4, 'A validação previne a reabertura porque, se o pedido já foi testado e validado com dados, quem pedir de novo pode ser direcionado ao registro da validação em vez de reiniciar a discussão.', 'Nota cheia: explica que a validação com dados serve como prova e evita reiniciar a discussão. Metade: diz que a validação ajuda, sem explicar como previne reabertura. Zero: não explica, em branco ou fora do tema.'),
      (v_atividade, 15, 1, 'Cite uma regra da etapa de comunicação', 0.2, 'Uma regra é explicar o motivo técnico da decisão em linguagem acessível, sem jargões desnecessários.', 'Nota cheia: cita uma regra da etapa de comunicação (explicar motivo técnico em linguagem acessível). Metade: cita uma regra vaga, como "ser claro". Zero: não cita regra, em branco ou fora do tema.'),
      (v_atividade, 15, 2, 'Explique por que é importante informar sobre pedidos que não serão atendidos', 0.4, 'É importante informar para que os usuários saibam que seus pedidos foram lidos e considerados, mesmo que não atendidos, mantendo a confiança e a transparência.', 'Nota cheia: explica que informar mantém a confiança e a transparência, mostrando que o pedido foi considerado. Metade: diz que é importante informar, sem explicar o motivo. Zero: diz que não é necessário informar, em branco ou fora do tema.'),
      (v_atividade, 15, 3, 'Indique como você comunicaria uma recusa ao usuário', 0.4, 'Comunicaria a recusa explicando o motivo técnico de forma respeitosa, por exemplo: "Após testes, vimos que esse recurso prejudicaria a velocidade do aplicativo, então não vamos implementar".', 'Nota cheia: descreve a comunicação com motivo técnico e forma respeitosa, com exemplo. Metade: descreve a comunicação sem o motivo técnico ou sem o respeito. Zero: não descreve ou descreve de forma hostil, em branco ou fora do tema.'),
      (v_atividade, 16, 1, 'Indique o momento ideal para mapear conflitos', 0.2, 'O momento ideal é antes de começar a desenhar, quando ainda é fácil ajustar o plano sem reescrever código.', 'Nota cheia: indica que é antes de começar a desenhar, quando é fácil ajustar o plano. Metade: indica um momento genérico, como "durante o projeto". Zero: indica "depois de pronto", em branco ou fora do tema.'),
      (v_atividade, 16, 2, 'Explique por que ignorar conflitos até o final gera retrabalho', 0.4, 'Ignorar conflitos até o final gera retrabalho porque, quando o problema aparece após o código pronto, é preciso reescrever partes do sistema, o que custa tempo e esforço.', 'Nota cheia: explica que ignorar conflitos até o final leva a reescrever código pronto, custando tempo e esforço. Metade: diz que gera retrabalho, sem explicar o custo ou o código pronto. Zero: diz que não gera retrabalho, em branco ou fora do tema.'),
      (v_atividade, 16, 3, 'Indique como o mapeamento antecipado melhora a comunicação com programadores', 0.4, 'O mapeamento antecipado mostra aos programadores os pontos críticos antes da implementação, permitindo que eles opinem sobre viabilidade técnica e alternativas desde o início.', 'Nota cheia: explica que o mapeamento antecipado mostra pontos críticos e permite opinião técnica antes da implementação. Metade: diz que melhora a comunicação, sem explicar como. Zero: não explica, em branco ou fora do tema.'),
      (v_atividade, 17, 1, 'Explique por que a mediação não deve ser feita só pelo designer', 0.2, 'A mediação não deve ser feita só pelo designer porque ele pode ter um viés de projeto e não considerar as limitações técnicas ou o ponto de vista dos programadores.', 'Nota cheia: explica que o designer pode ter viés e não considerar limitações técnicas ou o ponto de vista dos programadores. Metade: diz que não deve ser só o designer, sem explicar o motivo. Zero: diz que o designer deve decidir sozinho, em branco ou fora do tema.'),
      (v_atividade, 17, 2, 'Indique quem deve participar da mediação', 0.4, 'Devem participar o designer, programadores e representantes dos usuários (ou clientes), para que todos os lados sejam ouvidos antes da decisão.', 'Nota cheia: indica designer, programadores e representantes de usuários/clientes. Metade: indica apenas um ou dois desses grupos. Zero: indica só um grupo ou não responde, em branco ou fora do tema.'),
      (v_atividade, 17, 3, 'Explique como a participação diversificada melhora a decisão', 0.4, 'A participação diversificada melhora a decisão porque traz múltiplas perspectivas (técnica, de design e de usuário), reduzindo o risco de escolher soluções inviáveis ou que não atendam a necessidade real.', 'Nota cheia: explica que múltiplas perspectivas reduzem o risco de soluções inviáveis ou inadequadas. Metade: diz que melhora a decisão, sem explicar como as perspectivas ajudam. Zero: não explica, em branco ou fora do tema.'),
      (v_atividade, 18, 1, 'Explique o objetivo da mediação de conflitos', 0.2, 'O objetivo da mediação é encontrar uma solução que atenda ao núcleo das necessidades dos lados em conflito, sem que nenhum lado perca o essencial.', 'Nota cheia: explica que o objetivo é encontrar solução que atenda ao núcleo das necessidades de ambos os lados. Metade: explica que é resolver o conflito, sem detalhar o núcleo das necessidades. Zero: não explica ou explica de forma errada, em branco ou fora do tema.'),
      (v_atividade, 18, 2, 'Indique a diferença entre mediação e arbitragem', 0.4, 'Mediação busca uma solução conjunta que atenda ambos os lados; arbitragem impõe uma decisão de cima para baixo, sem negociação.', 'Nota cheia: diferencia mediação (solução conjunta) de arbitragem (decisão imposta). Metade: menciona apenas um dos dois conceitos. Zero: confunde os conceitos, em branco ou fora do tema.'),
      (v_atividade, 18, 3, 'Explique por que a mediação preserva a cooperação', 0.4, 'A mediação preserva a cooperação porque todos os lados participam da construção da solução e sentem que foram ouvidos, o que mantém o respeito e a vontade de colaborar.', 'Nota cheia: explica que a participação de todos na construção da solução mantém o respeito e a cooperação. Metade: diz que preserva a cooperação, sem explicar o mecanismo. Zero: não explica, em branco ou fora do tema.'),
      (v_atividade, 19, 1, 'Explique por que conflitos são comuns em projetos com muitos usuários', 0.2, 'Conflitos são comuns porque diferentes perfis têm necessidades, rotinas e limitações distintas, e o que um grupo precisa pode atrapalhar outro.', 'Nota cheia: explica que diferentes perfis têm necessidades e rotinas distintas, e o que ajuda um pode atrapalhar outro. Metade: diz que conflitos são comuns, sem explicar por que. Zero: diz que conflitos não devem existir, em branco ou fora do tema.'),
      (v_atividade, 19, 2, 'Explique como conflitos podem ser benéficos se bem geridos', 0.4, 'Conflitos bem geridos revelam pontos cegos do projeto e levam a soluções mais robustas, pois forçam a equipe a considerar múltiplas perspectivas antes de decidir.', 'Nota cheia: explica que conflitos revelam pontos cegos e levam a soluções mais robustas ao considerar múltiplas perspectivas. Metade: diz que podem ser benéficos, sem explicar como. Zero: diz que conflitos só são negativos, em branco ou fora do tema.'),
      (v_atividade, 19, 3, 'Indique o que aconteceria se conflitos fossem ignorados', 0.4, 'Se conflitos fossem ignorados, a equipe tomaria decisões baseadas em um só lado, e a solução final poderia não atender a maioria dos usuários, gerando retrabalho e insatisfação.', 'Nota cheia: explica que ignorar conflitos leva a decisões baseadas em um só lado e insatisfação da maioria. Metade: diz que gera problemas, sem explicar o mecanismo. Zero: diz que ignorar conflitos não tem problema, em branco ou fora do tema.'),
      (v_atividade, 20, 1, 'Indique a situação descrita', 0.2, 'A situação é a tela de agendamento de consultas do aplicativo do hospital, onde estudantes e professores usam o mesmo sistema com necessidades diferentes.', 'Nota cheia: indica a tela de agendamento e os dois perfis (estudantes e professores) com necessidades diferentes. Metade: indica apenas a tela ou apenas os perfis. Zero: não indica a situação, em branco ou fora do tema.'),
      (v_atividade, 20, 2, 'Identifique os lados em conflito', 0.4, 'Os lados em conflito são os estudantes, que querem rapidez e agilidade no celular, e os professores, que precisam de campos completos e relatórios.', 'Nota cheia: identifica estudantes (rapidez) e professores (campos completos e relatórios) como lados em conflito. Metade: identifica apenas um lado ou os lados sem as necessidades. Zero: não identifica os lados, em branco ou fora do tema.'),
      (v_atividade, 20, 3, 'Proponha uma abordagem de mediação para resolver o conflito', 0.4, 'Uma abordagem é ouvir ambos os lados, mapear as necessidades essenciais de cada um, testar uma alternativa que atenda ao núcleo de ambos (por exemplo, um formulário adaptável que mostra mais campos apenas quando necessário) e validar com os usuários.', 'Nota cheia: propõe abordagem com ouvir os lados, mapear necessidades, testar alternativa que atenda ao núcleo de ambos e validar. Metade: propõe apenas parte dos passos ou uma solução unilateral. Zero: não propõe abordagem, em branco ou fora do tema.');
end $$;
